$reviewedEditorialContext = [
    'han' => ['upper_lower_ensemble', '全国不同地域、时期与社会场景中的汉族着装实践', 'Han dress practices across regions, periods, and social settings in China', '单张照片不能确认朝代、阶层、复原依据或礼仪身份；交领、裙装或圆领等结构也必须分别核对，不能只凭“古风”归为汉服。', 'One photograph cannot establish dynasty, rank, reconstruction basis, or ritual status; cross collars, skirts, and round collars require separate construction checks rather than a generic historical look.'],
    'mongol' => ['robe_system', '内蒙古及相关地区牧区、农区与城镇中的蒙古族社区', 'Mongol communities in pastoral, agricultural, and urban settings in Inner Mongolia and related regions', '蒙古袍照片不能单独证明旗属、地方款式、季节、年代或活动角色，也不能因长袍轮廓被归为汉服。', 'A robe image alone cannot establish banner affiliation, local form, season, date, or participant role, and a long silhouette is not evidence of Hanfu.'],
    'hui' => ['religious_modesty_dress', '宁夏、甘肃、青海及其他地区具有不同地方实践的回族社区', 'Hui communities with differing local practices in Ningxia, Gansu, Qinghai, and elsewhere', '白帽、盖头或端庄长衣不能单独确认信仰实践、地区、性别规范或礼仪身份，更不能被改称汉服。', 'A white cap, head covering, or modest long garment cannot by itself establish religious practice, locality, gender convention, or ritual status, and must not be relabelled as Hanfu.'],
    'tibetan' => ['robe_system', '西藏、青海、四川等高原地区具有明显地方差异的藏族社区', 'Tibetan communities with substantial local variation across Tibet, Qinghai, Sichuan, and other plateau regions', '一张藏袍照片不能确认地区支系、季节、身份、年代或仪式用途；围裹长袍也不能仅凭轮廓与汉服袍服互换命名。', 'One chuba image cannot establish locality, branch, season, status, date, or ceremonial use, and a wrapped robe silhouette is not interchangeable with a Hanfu robe.'],
    'uyghur' => ['robe_system', '新疆不同绿洲、城镇与乡村中的维吾尔族社区', 'Uyghur communities across different oases, towns, and rural areas of Xinjiang', '花帽、袷袢或艾德莱斯纹样不能单独确认地区、年代、婚姻状态或活动角色，也不能据此推断整套服装。', 'A doppa, chapan, or atlas pattern alone cannot establish locality, date, marital status, or event role, nor prove the rest of an ensemble.'],
    'miao' => ['upper_lower_ensemble', '贵州、湖南、云南等地不同县寨与支系的苗族社区', 'Miao communities across many counties and branches in Guizhou, Hunan, Yunnan, and beyond', '苗族服饰地方类型很多；一张银饰盛装照不能确认县寨、支系、年代、婚姻状态或礼仪角色。', 'Miao dress has many local systems; one silver-rich formal portrait cannot establish village, branch, date, marital status, or ritual role.'],
    'yi' => ['cape_outerwear_system', '四川、云南、贵州不同地方传统中的彝族社区', 'Yi communities within distinct local traditions in Sichuan, Yunnan, and Guizhou', '擦尔瓦、百褶裙或英雄结不能单独确认支系、地区、年代与角色；外披轮廓也不能被当作通用“民族风”。', 'A chaerwa, pleated skirt, or hero knot alone cannot establish branch, locality, date, or role, and an outerwear silhouette is not a generic ethnic style.'],
    'zhuang' => ['upper_lower_ensemble', '广西及周边地区具有语言与地方差异的壮族社区', 'Zhuang communities with linguistic and local variation in Guangxi and neighbouring areas', '壮锦或深色短衣不能单独确认地区、支系、年代或场合；相似几何纹样也不是族属证明。', 'Zhuang brocade or a dark jacket alone cannot establish locality, branch, date, or occasion, and similar geometry is not proof of ethnicity.'],
    'buyei' => ['upper_lower_ensemble', '贵州不同县域与村寨中的布依族社区', 'Buyei communities across different counties and villages in Guizhou', '靛蓝、蜡染或百褶裙不能单独确认村寨、年代、穿着次序或礼俗角色；需保留完整上下装视角。', 'Indigo, batik, or a pleated skirt alone cannot establish village, date, dressing sequence, or ceremonial role; complete upper-and-lower views are required.'],
    'korean' => ['upper_lower_ensemble', '吉林延边等地具有当代与礼俗差异的朝鲜族社区', 'Korean (Chaoxian) communities in Yanbian and elsewhere with contemporary and ceremonial variation', '短袄长裙的照片不能单独确认年代、场合、婚姻状态或地区，也不能与韩国不同历史时期服饰无条件互换。', 'A jeogori-and-skirt image alone cannot establish date, occasion, marital status, or locality, and cannot be freely substituted for Korean dress from other periods and places.'],
    'manchu' => ['robe_system', '东北与北京等地承载不同历史记忆和当代实践的满族社区', 'Manchu communities in Northeast China, Beijing, and elsewhere with varied historical memories and present practice', '斜襟长袍、马褂或旗鞋不能单独确认清代身份、品级、年代或当代族属；旗袍演变也需分期说明。', 'A side-fastening robe, magua, or platform shoe alone cannot establish Qing identity, rank, date, or present ethnicity; qipao development also requires dated context.'],
    'dong' => ['upper_lower_ensemble', '贵州、湖南、广西不同侗语区与村寨中的侗族社区', 'Dong communities across different language areas and villages in Guizhou, Hunan, and Guangxi', '亮布、百褶裙或银饰不能单独确认村寨、支系、年代或节庆角色，侗布表面也不能从照片直接证明工序。', 'Glazed cloth, a pleated skirt, or silver alone cannot establish village, branch, date, or festival role, and a photograph cannot prove the making process of Dong cloth.'],
    'yao' => ['trousers_jacket_system', '广西、湖南、云南等地多种地方支系中的瑶族社区', 'Yao communities across numerous local branches in Guangxi, Hunan, Yunnan, and beyond', '头帕、绣花衣裤或银饰不能单独确认支系、地区、年代、婚姻状态或盘王节角色。', 'A headscarf, embroidered jacket-and-trouser set, or silver cannot alone establish branch, locality, date, marital status, or Panwang-festival role.'],
    'bai' => ['upper_lower_ensemble', '云南大理及周边不同地方实践中的白族社区', 'Bai communities in Dali and surrounding areas with differing local practices', '白蓝配色、头巾或扎染不能单独确认地区、年代、婚姻状态或节庆身份；扎染外观不能证明手工来源。', 'White-and-blue colour, a headdress, or tie-dye alone cannot establish locality, date, marital status, or festival identity, and appearance cannot prove handmade provenance.'],
    'tujia' => ['craft_object_led', '湘鄂渝黔交界不同县域中的土家族社区', 'Tujia communities across counties at the Hunan-Hubei-Chongqing-Guizhou borderlands', '西兰卡普或对襟衣不能单独确认制作者、地区、年代、用途或族属；织锦图案须与工艺和出处同时记录。', 'Xilankapu or a front-opening jacket alone cannot establish maker, locality, date, use, or ethnicity; brocade pattern must be recorded with technique and provenance.'],
    'hani' => ['upper_lower_ensemble', '云南红河及周边具有梯田地区差异的哈尼族社区', 'Hani communities in Honghe and nearby areas with local variation across terrace regions', '靛蓝短衣、银泡或头饰不能单独确认地区支系、年代、婚姻状态或节庆角色。', 'An indigo jacket, silver studs, or headdress alone cannot establish local branch, date, marital status, or festival role.'],
    'kazakh' => ['robe_system', '新疆北部牧区、城镇与不同迁徙背景中的哈萨克族社区', 'Kazakh communities in pastoral and urban northern Xinjiang with varied migration histories', '袷袢、毛皮帽或刺绣裙不能单独确认地区、季节、年代、婚姻状态或活动角色。', 'A chapan, fur hat, or embroidered dress alone cannot establish locality, season, date, marital status, or event role.'],
