    'russian' => ['upper_lower_ensemble', '新疆、内蒙古等地具有不同迁徙和家庭历史的俄罗斯族社区', 'Russian communities in Xinjiang, Inner Mongolia, and elsewhere with differing migration and family histories', '头巾、衬衫或长裙不能单独确认地区、年代、婚姻状态、宗教实践或节庆角色。', 'A headscarf, blouse, or long skirt alone cannot establish locality, date, marital status, religious practice, or festival role.'],
    'ewenki' => ['cape_outerwear_system', '内蒙古、黑龙江不同森林与草原生活背景中的鄂温克族社区', 'Ewenki communities in forest and grassland settings across Inner Mongolia and Heilongjiang', '皮袍、毛皮帽或靴不能单独确认地区、季节、年代、身份或瑟宾节角色；材料种类需实物证明。', 'A hide robe, fur hat, or boot alone cannot establish locality, season, date, identity, or Sebin-festival role; material species requires object evidence.'],
    'deang' => ['wrap_tube_skirt_system', '云南德宏、临沧不同村寨与地方传统中的德昂族社区', 'Deang communities across villages and local traditions in Dehong and Lincang', '短衣、筒裙或腰箍不能单独确认村寨、年代、婚姻状态或浇花节角色；腰饰意义需地方资料。', 'A short jacket, tube skirt, or waist hoop alone cannot establish village, date, marital status, or Watering-Flowers-Festival role; waist-ornament meaning needs a local source.'],
    'bonan' => ['religious_modesty_dress', '甘肃积石山及周边具有不同家庭与地方实践的保安族社区', 'Bonan communities in Jishishan and nearby areas with varied family and local practices', '盖头、白帽、长衫或坎肩不能单独确认信仰实践、地区、性别规范、年代或礼仪身份。', 'A head covering, white cap, robe, or vest alone cannot establish religious practice, locality, gender convention, date, or ritual status.'],
    'yugur' => ['robe_system', '甘肃肃南不同语言群体与牧区中的裕固族社区', 'Yugur communities across language groups and pastoral areas in Sunan', '长袍、皮帽或高筒靴不能单独确认语言群体、地区、季节、年代或身份。', 'A robe, fur hat, or tall boot alone cannot establish language group, locality, season, date, or identity.'],
    'gin' => ['trousers_jacket_system', '广西东兴沿海三岛及周边地区的京族社区', 'Gin communities on the coastal islands and surrounding areas of Dongxing, Guangxi', '短衫、宽裤或斗笠不能单独确认地点、年代、身份或哈节角色；渔业场景也不是族属证明。', 'A short shirt, wide trousers, or conical hat alone cannot establish place, date, identity, or Ha-festival role; a fishing scene is not proof of ethnicity.'],
    'tatar' => ['upper_lower_ensemble', '新疆不同城镇与多民族交往环境中的塔塔尔族社区', 'Tatar communities across Xinjiang towns and multi-ethnic settings', '短衣、长裙、绣帽或皮靴不能单独确认地区、年代、婚姻状态或撒班节角色。', 'A jacket, long skirt, embroidered cap, or leather boot alone cannot establish locality, date, marital status, or Sabantuy role.'],
    'derung' => ['cape_outerwear_system', '云南贡山独龙江流域不同村寨中的独龙族社区', 'Derung communities across villages in the Dulong River valley of Gongshan', '独龙毯的条纹与披裹方式不能单独确认村寨、年代、穿着者身份或卡雀哇角色；织物需记录正反面。', 'The stripes or drape of a Derung blanket alone cannot establish village, date, wearer identity, or Kaquewa role; both faces of the textile require documentation.'],
    'oroqen' => ['cape_outerwear_system', '内蒙古、黑龙江不同森林地区中的鄂伦春族社区', 'Oroqen communities across forest regions in Inner Mongolia and Heilongjiang', '狍皮袍、皮帽或靴不能单独确认地区、季节、年代、身份或篝火活动角色；动物材料需实物出处。', 'A roe-hide coat, hat, or boot alone cannot establish locality, season, date, identity, or bonfire-event role; animal material requires object provenance.'],
    'hezhen' => ['cape_outerwear_system', '黑龙江流域不同聚落中的赫哲族社区与鱼皮技艺传承者', 'Hezhen communities and fish-skin craft practitioners across settlements of the Heilongjiang river region', '鱼皮衣外观不能单独确认鱼种、制作者、聚落、年代、身份或乌日贡角色；材料与鞣制需实物记录。', 'The appearance of fish-skin clothing cannot establish species, maker, settlement, date, identity, or Wurigong role; material and tanning require object records.'],
    'monba' => ['robe_system', '西藏墨脱及周边不同河谷与村落中的门巴族社区', 'Monba communities across valleys and villages in Motuo and nearby areas', '藏式长袍变体、围裙或厚靴不能单独确认村落、季节、年代、身份或收获活动角色。', 'A chuba variant, apron, or thick boot alone cannot establish village, season, date, identity, or harvest-event role.'],
    'lhoba' => ['cape_outerwear_system', '西藏东南不同地方群体与村落中的珞巴族社区', 'Lhoba communities across local groups and villages in southeast Tibet', '兽皮背心、藤编或珠饰裙不能单独确认地方群体、材料种类、年代、身份或收获活动角色。', 'A hide vest, rattan element, or beaded skirt alone cannot establish local group, material species, date, identity, or harvest-event role.'],
    'jino' => ['upper_lower_ensemble', '云南景洪基诺山不同村寨中的基诺族社区', 'Jino communities across villages of Jino Mountain in Jinghong', '白色对襟衣、白裙或包头不能单独确认村寨、年代、身份或特懋克节角色；浅色也不是族属证据。', 'A white front-opening jacket, skirt, or head wrap alone cannot establish village, date, identity, or Temoke-festival role, and pale colour is not proof of ethnicity.'],
];

if (count($reviewedEditorialContext) !== 56) {
    throw new RuntimeException('hanfu_r3_reviewed_ethnic_context_count_invalid');
}
foreach ($profiles as &$profile) {
    $code = strtolower((string)$profile['code']);
    $context = $reviewedEditorialContext[$code] ?? throw new RuntimeException('hanfu_r3_reviewed_ethnic_context_missing:' . $code);
    [$family, $community, $communityEn, $limit, $limitEn] = $context;
    $profile['community'] = $community;
    $profile['community_en'] = $communityEn;
    $profile['inference_limit'] = $limit;
    $profile['inference_limit_en'] = $limitEn;
    $profile['editorial_family'] = $family;
    $profile['evidence_keys'] = ['neac-' . $code, 'neac-' . $code . '-overview'];
    if ($code === 'li') {
        $profile['evidence_keys'][] = 'unesco-li-textile';
    }
}
unset($profile);

return $profiles;
